<div class="col-lg-5"><div class="card border-0 shadow-sm overflow-hidden h-100"><div class="p-3"><h2 class="h5 mb-1">Main headquarters</h2><p class="text-secondary small mb-0"><?=e(setting('business_location','Set the headquarters address in Admin → Store settings.'))?></p></div><?php $hqAddress=trim((string)setting('business_location','')); $hqMap=trim((string)setting('headquarters_map_embed_url','')); if($hqMap!=='' && preg_match('~^https://(www\.)?google\.com/maps/embed\?~i',$hqMap)):?><iframe class="contact-map" src="<?=e($hqMap)?>" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen title="Map to main headquarters"></iframe><?php elseif($hqAddress!==''):?><iframe class="contact-map" src="https://www.google.com/maps?q=<?=rawurlencode($hqAddress)?>&output=embed" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen title="Map to main headquarters"></iframe><?php else:?><div class="p-4 text-secondary">Add the headquarters address in Store settings to display its map here.</div><?php endif;?></div></div></div>
